14.1 Panel interactivo




Código
viewof radio_um = Inputs.range(
  [2, 30],
  {
    value: 10,
    step: 1,
    label: "Radio celular a [µm]"
  }
)









Código
viewof campo_kVm = Inputs.range(
  [10, 300],
  {
    value: 120,
    step: 10,
    label: "Campo externo E₀ [kV/m]"
  }
)









Código
viewof umbral_V = Inputs.range(
  [0.1, 3.0],
  {
    value: 1.0,
    step: 0.1,
    label: "Umbral de referencia [V]"
  }
)









Código
a_m = radio_um * 1e-6
E0_Vm = campo_kVm * 1e3

theta = Array.from(
  {length: 401},
  (_, i) =&gt; i * Math.PI / 400
)

datos = theta.map(t =&gt; ({
  theta: t,
  deltaV: 1.5 * a_m * E0_Vm * Math.cos(t)
}))

deltaVmax = 1.5 * a_m * E0_Vm

datosUmbral = datos.filter(d =&gt; Math.abs(d.deltaV) &gt;= umbral_V)














































Código
html`
&lt;div style="
  border: 1px solid #d0d7de;
  border-radius: 10px;
  padding: 1rem;
  margin-top: 1rem;
  background: #f8fafc;
  font-size: 0.95rem;
"&gt;
  &lt;h4 style="margin-top:0;"&gt;Valores usados&lt;/h4&gt;
  &lt;ul style="padding-left:1.2rem;"&gt;
    &lt;li&gt;&lt;b&gt;Radio celular:&lt;/b&gt;&lt;br&gt;${radio_um.toFixed(1)} µm = ${a_m.toExponential(2)} m&lt;/li&gt;
    &lt;li&gt;&lt;b&gt;Campo externo:&lt;/b&gt;&lt;br&gt;${campo_kVm.toFixed(1)} kV/m = ${E0_Vm.toExponential(2)} V/m&lt;/li&gt;
    &lt;li&gt;&lt;b&gt;Voltaje máximo inducido:&lt;/b&gt;&lt;br&gt;${deltaVmax.toFixed(3)} V&lt;/li&gt;
    &lt;li&gt;&lt;b&gt;Umbral seleccionado:&lt;/b&gt;&lt;br&gt;${umbral_V.toFixed(2)} V&lt;/li&gt;
  &lt;/ul&gt;
  &lt;p style="margin-bottom:0;"&gt;
    Condición aproximada:
    &lt;br&gt;
    &lt;b&gt;|ΔV&lt;sub&gt;m&lt;/sub&gt;&lt;sup&gt;ind&lt;/sup&gt;| ≥ ${umbral_V.toFixed(2)} V&lt;/b&gt;
  &lt;/p&gt;
&lt;/div&gt;
`










Código
Plot.plot({
  width: 500,
  height: 420,
  marginLeft: 75,
  marginRight: 25,
  marginTop: 25,
  marginBottom: 60,
  grid: true,
  x: {
    label: "Ángulo polar θ [rad] →",
    domain: [0, Math.PI],
    ticks: [0, Math.PI / 2, Math.PI],
    tickFormat: d =&gt; {
      if (Math.abs(d) &lt; 1e-6) return "0";
      if (Math.abs(d - Math.PI / 2) &lt; 1e-6) return "π/2";
      if (Math.abs(d - Math.PI) &lt; 1e-6) return "π";
      return d.toFixed(2);
    }
  },
  y: {
    label: "↑ ΔVm inducido [V]"
  },
  marks: [
    Plot.ruleY([0], {
      stroke: "black",
      strokeOpacity: 0.55
    }),

    Plot.ruleY([umbral_V], {
      stroke: "#6b7280",
      strokeDasharray: "5,5",
      strokeOpacity: 0.75
    }),

    Plot.ruleY([-umbral_V], {
      stroke: "#6b7280",
      strokeDasharray: "5,5",
      strokeOpacity: 0.75
    }),

    Plot.line(datos, {
      x: "theta",
      y: "deltaV",
      stroke: "#1f4e79",
      strokeWidth: 3
    }),

    Plot.line(datosUmbral, {
      x: "theta",
      y: "deltaV",
      stroke: "#d95f02",
      strokeWidth: 6
    }),

    Plot.dot(datosUmbral, {
      x: "theta",
      y: "deltaV",
      r: 2.5,
      fill: "#d95f02"
    }),

    Plot.text(
      [
        {theta: 0.08, deltaV: umbral_V, label: "+ umbral"},
        {theta: 0.08, deltaV: -umbral_V, label: "- umbral"}
      ],
      {
        x: "theta",
        y: "deltaV",
        text: "label",
        dy: -8,
        fontSize: 12,
        fill: "#374151"
      }
    )
  ]
})

