Plot.plot({
  width: 500,
  height: 420,
  marginLeft: 75,
  marginRight: 25,
  marginTop: 25,
  marginBottom: 60,
  grid: true,
  x: {
    label: "Ángulo polar θ [rad] →",
    domain: [0, Math.PI],
    ticks: [0, Math.PI / 2, Math.PI],
    tickFormat: d =&gt; {
      if (Math.abs(d) &lt; 1e-6) return "0";
      if (Math.abs(d - Math.PI / 2) &lt; 1e-6) return "π/2";
      if (Math.abs(d - Math.PI) &lt; 1e-6) return "π";
      return d.toFixed(2);
    }
  },
  y: {
    label: "↑ ΔVm inducido [V]"
  },
  marks: [
    Plot.ruleY([0], {
      stroke: "black",
      strokeOpacity: 0.55
    }),

    Plot.ruleY([umbral_V], {
      stroke: "#6b7280",
      strokeDasharray: "5,5",
      strokeOpacity: 0.75
    }),

    Plot.ruleY([-umbral_V], {
      stroke: "#6b7280",
      strokeDasharray: "5,5",
      strokeOpacity: 0.75
    }),

    Plot.line(datos, {
      x: "theta",
      y: "deltaV",
      stroke: "#1f4e79",
      strokeWidth: 3
    }),

    Plot.line(datosUmbral, {
      x: "theta",
      y: "deltaV",
      stroke: "#d95f02",
      strokeWidth: 6
    }),

    Plot.dot(datosUmbral, {
      x: "theta",
      y: "deltaV",
      r: 2.5,
      fill: "#d95f02"
    }),

    Plot.text(
      [
        {theta: 0.08, deltaV: umbral_V, label: "+ umbral"},
        {theta: 0.08, deltaV: -umbral_V, label: "- umbral"}
      ],
      {
        x: "theta",
        y: "deltaV",
        text: "label",
        dy: -8,
        fontSize: 12,
        fill: "#374151"
      }
    )
  ]
